#import "SpotifyLyrics.h"
#import <math.h>
NSArray<NSDictionary *> *TMParseLRC(NSString *input){if(![input isKindOfClass:NSString.class]||input.length>200000)return @[];
 NSRegularExpression *stamp=[NSRegularExpression regularExpressionWithPattern:@"\\[(\\d{1,3}):(\\d{2})(?:[.:](\\d{1,3}))?\\]" options:0 error:nil],*offsetRE=[NSRegularExpression regularExpressionWithPattern:@"\\[offset:([+-]?\\d+)\\]" options:NSRegularExpressionCaseInsensitive error:nil];
 NSTextCheckingResult *off=[offsetRE firstMatchInString:input options:0 range:NSMakeRange(0,input.length)];NSInteger offset=off?[[input substringWithRange:[off rangeAtIndex:1]]integerValue]:0;offset=MAX(-60000,MIN(60000,offset));NSMutableArray *rows=[NSMutableArray new];
 for(NSString *line in [input componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]){NSArray *matches=[stamp matchesInString:line options:0 range:NSMakeRange(0,line.length)];if(!matches.count)continue;
  NSString *text=[[line substringFromIndex:NSMaxRange([matches.lastObject range])]stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];text=[[text componentsSeparatedByCharactersInSet:NSCharacterSet.controlCharacterSet]componentsJoinedByString:@""];if(!text.length)continue;
  for(NSTextCheckingResult *m in matches){NSInteger min=[[line substringWithRange:[m rangeAtIndex:1]]integerValue],sec=[[line substringWithRange:[m rangeAtIndex:2]]integerValue];if(sec>59)continue;NSRange r=[m rangeAtIndex:3];NSString *frac=r.location==NSNotFound?@"":[line substringWithRange:r];NSInteger ms=frac.integerValue*(frac.length==1?100:frac.length==2?10:1);NSInteger t=MAX(0,(min*60+sec)*1000+ms+offset);if(t<=86400000)[rows addObject:@{@"ms":@(t),@"text":text}];}
 }[rows sortUsingComparator:^NSComparisonResult(id a,id b){return [a[@"ms"] compare:b[@"ms"]];}];return rows.count>192?[rows subarrayWithRange:NSMakeRange(0,192)]:rows;
}
static NSDictionary *None(void){return @{ @"kind":@"none", @"rows":@[] };}
NSURL *TMLRCLIBGetURL(NSString *title,NSString *artist,NSString *album,uint32_t durationMs){if(!title.length||!artist.length)return nil;NSURLComponents *c=[NSURLComponents componentsWithString:@"https://lrclib.net/api/get"];c.queryItems=@[[NSURLQueryItem queryItemWithName:@"track_name" value:title],[NSURLQueryItem queryItemWithName:@"artist_name" value:artist],[NSURLQueryItem queryItemWithName:@"duration" value:[NSString stringWithFormat:@"%ld",lround(durationMs/1000.0)]]];c.percentEncodedQuery=[c.percentEncodedQuery stringByReplacingOccurrencesOfString:@"+" withString:@"%2B"];return c.URL;}
NSURL *TMLRCLIBSearchURL(NSString *title,NSString *artist){if(!title.length||!artist.length)return nil;NSURLComponents *c=[NSURLComponents componentsWithString:@"https://lrclib.net/api/search"];c.queryItems=@[[NSURLQueryItem queryItemWithName:@"track_name" value:title],[NSURLQueryItem queryItemWithName:@"artist_name" value:artist]];c.percentEncodedQuery=[c.percentEncodedQuery stringByReplacingOccurrencesOfString:@"+" withString:@"%2B"];return c.URL;}
static NSDictionary *RowsForObject(id obj){if(![obj isKindOfClass:NSDictionary.class])return None();id synced=obj[@"syncedLyrics"];if([synced isKindOfClass:NSString.class]){NSArray *rows=TMParseLRC(synced);return rows.count?@{@"kind":@"synced",@"rows":rows}:None();}id instrumental=obj[@"instrumental"];if([instrumental isKindOfClass:NSNumber.class]&&[instrumental boolValue])return @{@"kind":@"instrumental",@"rows":@[]};return None();}
NSDictionary *TMLRCLIBRows(NSData *body,NSInteger status,uint32_t durationMs){if(status!=200||!body.length)return None();id obj=[NSJSONSerialization JSONObjectWithData:body options:0 error:nil];if([obj isKindOfClass:NSDictionary.class])return RowsForObject(obj);if([obj isKindOfClass:NSArray.class])for(id item in obj){if(![item isKindOfClass:NSDictionary.class]||![item[@"syncedLyrics"] isKindOfClass:NSString.class])continue;id duration=item[@"duration"];if(![duration isKindOfClass:NSNumber.class])continue;double dur=[duration doubleValue];if(!isfinite(dur)||dur<0)continue;if(fabs(dur-durationMs/1000.0)<=2){NSDictionary *r=RowsForObject(item);if([r[@"kind"] isEqual:@"synced"])return r;}}return None();}
@interface TMSpotifyLyrics()@property(nonatomic,copy)TMSpotifyHTTP http;@property NSCache *cache;@end
@implementation TMSpotifyLyrics
+ (instancetype)shared{static TMSpotifyLyrics *s;static dispatch_once_t once;dispatch_once(&once,^{s=[[self alloc]initWithHTTP:TMSpotifyDefaultHTTP()];});return s;}
- (instancetype)initWithHTTP:(TMSpotifyHTTP)http{if((self=[super init])){_http=[http copy];_cache=[NSCache new];_cache.countLimit=50;}return self;}
- (void)lyricsForID:(NSString *)trackID title:(NSString *)title artist:(NSString *)artist album:(NSString *)album durationMs:(uint32_t)durationMs done:(void(^)(NSArray *,NSString *,BOOL))done{NSDictionary *hit=trackID.length?[_cache objectForKey:trackID]:nil;if(hit){if(done)done(hit[@"rows"],hit[@"kind"],NO);return;}NSURL *get=TMLRCLIBGetURL(title,artist,album,durationMs);if(!get){if(done)done(@[],@"none",NO);return;}NSURLRequest *(^request)(NSURL *)=^NSURLRequest *(NSURL *u){NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:u];r.HTTPMethod=@"GET";[r setValue:@"TurboIO-ios107/1.0" forHTTPHeaderField:@"User-Agent"];return r;};__block void(^search)(void);__weak typeof(self) weak=self;search=^{TMSpotifyLyrics *self=weak;if(!self)return;NSURL *u=TMLRCLIBSearchURL(title,artist);self.http(request(u),^(NSData *b,NSHTTPURLResponse *resp,NSError *err){BOOL failed=err!=nil||(resp.statusCode>=500&&resp.statusCode<=599);NSDictionary *r=failed?None():TMLRCLIBRows(b,resp.statusCode,durationMs);NSString *kind=r[@"kind"];if([kind isEqual:@"synced"]&&trackID.length)[self.cache setObject:r forKey:trackID];if(done)done(r[@"rows"],kind,failed);});};self.http(request(get),^(NSData *b,NSHTTPURLResponse *resp,NSError *err){BOOL failed=err!=nil||(resp.statusCode>=500&&resp.statusCode<=599);NSDictionary *r=failed?None():TMLRCLIBRows(b,resp.statusCode,durationMs);if(failed){if(done)done(@[],@"none",YES);return;}if([r[@"kind"] isEqual:@"synced"]||[r[@"kind"] isEqual:@"instrumental"]){if(trackID.length)[self.cache setObject:r forKey:trackID];if(done)done(r[@"rows"],r[@"kind"],NO);return;}search();});}
@end
